// Auto-generated 1° equirectangular land mask (360x180) from world countries GeoJSON.
const HEX = "";
const BITS = new Uint8Array(8100);
for (let i = 0; i < 8100; i++) BITS[i] = parseInt(HEX.substr(i * 2, 2), 16);
export function isLandLatLon(latDeg: number, lonDeg: number): boolean {
  let row = Math.floor(90 - latDeg);  if (row < 0) row = 0; else if (row > 179) row = 179;
  let col = Math.floor(lonDeg + 180); if (col < 0) col = 0; else if (col > 359) col = 359;
  const idx = row * 360 + col;
  return (BITS[idx >> 3] & (1 << (idx & 7))) !== 0;
}
